"use client";

/**
 * Glow frame: a soft glowing border around the whole frame that pulses while
 * something is working, with a bright arc travelling around it. When the work
 * ends it calms to a steady primary line. Anything can sit inside.
 *
 * Written by Better Design.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import type { ReactNode } from "react";
import { AbsoluteFill, useCurrentFrame } from "remotion";
import { easings, mix, pickFont, progress, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "600"], subsets: ["latin"] });

/** Frames one pulse takes. */
const PULSE = 30;
/** Frames the glow takes to calm once the work ends. */
const SETTLE = 24;
const INSET = 28;
const MASK = "linear-gradient(oklch(0 0 0) 0 0)";

export interface GlowFrameProps {
  /** What sits inside the frame. Without it, a placeholder card shows the work and its end. */
  children?: ReactNode;
  /** Frames the border pulses before it settles to a steady line. */
  working?: number;
  /** Width of the border line, in pixels at 1920 wide. */
  thickness?: number;
  /** Status shown by the placeholder while it works, then when it is done. */
  workingLabel?: string;
  doneLabel?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

/** A pulsing glow around the frame that settles to a steady line when the work is done. */
export function GlowFrame({
  children,
  working = 90,
  thickness = 6,
  workingLabel = "Working on it",
  doneLabel = "Done",
  theme: themeOverride,
  font,
}: GlowFrameProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);

  const appear = easings.out(progress(frame, 0, 14));
  const calm = easings.inOut(progress(frame, working, SETTLE));
  const pulse = 0.5 - 0.5 * Math.cos((Math.min(frame, working) / PULSE) * Math.PI * 2);
  const glow = appear * (1 - calm) * (0.45 + 0.55 * pulse);
  // The arc travels while working, then spreads out into an even line.
  const angle = (Math.min(frame, working + SETTLE) / 75) * 360;
  const arc = mix(theme.primary, theme.primaryForeground, 0.55);
  const soft = withAlpha(theme.primary, 0.35 + 0.65 * calm);
  const ring = `conic-gradient(from ${angle}deg, ${soft}, ${theme.primary} 18%, ${mix(arc, theme.primary, calm)} 25%, ${theme.primary} 32%, ${soft} 50%, ${soft})`;
  const radius = theme.radius * 3;
  const edge = { position: "absolute", inset: INSET, borderRadius: radius } as const;

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family }}>
      <AbsoluteFill style={{ padding: INSET + thickness + 24, alignItems: "center", justifyContent: "center" }}>
        {children ?? <Placeholder theme={theme} done={calm} working={working} frame={frame} labels={[workingLabel, doneLabel]} />}
      </AbsoluteFill>
      <div
        style={{
          ...edge,
          opacity: appear,
          boxShadow: `0 0 ${40 + 70 * glow}px ${withAlpha(theme.primary, 0.7 * glow)}, inset 0 0 ${40 + 60 * glow}px ${withAlpha(theme.primary, 0.45 * glow)}`,
        }}
      />
      <div
        style={{
          ...edge,
          padding: thickness,
          opacity: appear,
          background: ring,
          mask: `${MASK} content-box exclude, ${MASK}`,
          WebkitMask: `${MASK} content-box, ${MASK}`,
          WebkitMaskComposite: "xor",
          filter: `blur(${glow * 1.5}px)`,
        }}
      />
    </AbsoluteFill>
  );
}

/** A card with a progress bar and status, standing in for the real content. */
function Placeholder({ theme, done, working, frame, labels }: { theme: VideoTheme; done: number; working: number; frame: number; labels: [string, string] }) {
  const fill = progress(frame, 6, Math.max(1, working - 6));
  const line = (w: number, o: number) => <div style={{ width: w, height: 22, borderRadius: 11, background: withAlpha(theme.foreground, o) }} />;
  return (
    <div style={{ width: 1040, padding: 64, borderRadius: theme.radius * 2, background: theme.card, border: `1px solid ${theme.border}`, display: "flex", flexDirection: "column", gap: 28 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 18 }}>
        <div style={{ position: "relative", width: 28, height: 28 }}>
          <div style={{ position: "absolute", inset: 0, borderRadius: 14, border: `3px solid ${withAlpha(theme.primary, 0.25)}`, borderTopColor: theme.primary, transform: `rotate(${frame * 12}deg)`, opacity: 1 - done }} />
          <div style={{ position: "absolute", inset: 0, borderRadius: 14, background: theme.primary, opacity: done, transform: `scale(${0.6 + 0.4 * done})` }} />
        </div>
        <div style={{ position: "relative", fontSize: 46, fontWeight: 600, color: theme.cardForeground }}>
          <span style={{ opacity: 1 - done }}>{labels[0]}</span>
          <span style={{ position: "absolute", left: 0, opacity: done }}>{labels[1]}</span>
        </div>
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
        {line(760, 0.1)}
        {line(620, 0.07)}
        {line(690, 0.07)}
      </div>
      <div style={{ height: 8, borderRadius: 4, background: withAlpha(theme.foreground, 0.08) }}>
        <div style={{ width: `${fill * 100}%`, height: "100%", borderRadius: 4, background: theme.primary }} />
      </div>
    </div>
  );
}
